import {Chess} from '../chess.js';
import {additionalOpeningLines} from './opening-variations.js';

export const CATEGORIES = ['Fundamentals', 'Tactics', 'Mating patterns', 'Pawn structures', 'Positional play', 'Defense', 'Endgames'];
export const DIFFICULTIES = ['Introductory', 'Intermediate', 'Advanced'];
export const THEME_NAMES = {mateIn1: 'Mate in one', mateIn2: 'Mate in two', fork: 'Forks', pin: 'Pins', skewer: 'Skewers', discoveredAttack: 'Discovered attacks', defensiveMove: 'Defense', promotion: 'Promotion', hangingPiece: 'Loose pieces', sacrifice: 'Sacrifices', backRankMate: 'Back-rank mates', endgame: 'Endgames'};
export const playUci = (chess, move) => chess.move({from: move.slice(0, 2), to: move.slice(2, 4), promotion: move[4]});
export const positionKey = fen => fen.split(' ').slice(0, 4).join(' ');
export function setup(pieces, turn = 'w') {
  const chess = new Chess('7k/8/8/8/8/8/8/K7 w - - 0 1');
  chess.clear();
  for (const [square, letter] of Object.entries(pieces)) if (letter) chess.put({type: letter.toLowerCase(), color: letter === letter.toUpperCase() ? 'w' : 'b'}, square);
  const fields = chess.fen().split(' '); fields[1] = turn; return fields.join(' ');
}
const sparse = pieces => setup({a1: 'K', h8: 'k', h2: 'P', a7: 'p', ...pieces});
const start = new Chess().fen();
const lineFen = san => {const c = new Chess(); for (const move of san.split(' ')) c.move(move); return c.fen();};
const example = (fen, moves, captions, highlights = []) => ({fen, moves, captions, highlights});
const square = (fen, prompt, rule, explanation, options = {}) => ({type: 'squares', fen, prompt, rule, explanation, ...options});
const move = (fen, prompt, objective, explanation, options = {}) => ({type: 'move', fen, prompt, objective, explanation, ...options});
const choice = (fen, prompt, options, answer, explanation) => ({type: 'choice', fen, prompt, options, answer, explanation});
const lesson = (id, title, category, level, concepts, explanation, why, examples, mistakes, exercises, prerequisites = []) =>
  ({id, title, category, level, concepts, explanation, why, examples, mistakes, exercises, prerequisites, source: 'Original Chess Review instruction and composed positions; GPL-3.0. Detector scope references are the existing concept catalog and retained research proofs.'});

